(async () => {
  const B = window.BareMetal
  const frames = n => new Promise(res => {
    let i = 0
    const step = () => (++i >= n ? res() : requestAnimationFrame(step))
    requestAnimationFrame(step)
  })
  const tap = () => {
    window.dispatchEvent(new KeyboardEvent('keydown', { code: 'KeyE', key: 'e', bubbles: true }))
    window.dispatchEvent(new KeyboardEvent('keyup', { code: 'KeyE', key: 'e', bubbles: true }))
  }
  const stands = {
    battery:    [-4.6, 5.0],
    carb:       [-3.3, -3.5],
    alternator: [-7.0, 0.6],
    radiator:   [-7.0, 2.25],
    plugs:      [-5.7, -3.6],
    wheels:     [5.7, 9.2]
  }
  const log = []
  for (const [part, [x, z]] of Object.entries(stands)) {
    const p = B.world.pickups[part]
    B.teleport(x, z)
    B.face(p.pos.x, p.pos.y + 0.1, p.pos.z)
    await frames(3)
    const seen = B.current && B.current.action
    tap()
    await frames(3)
    log.push({ part, seen, inv: B.game.s.inventory[part] || 0, taken: p.taken })
  }

  // mounts: stand and install each with the correct socket
  const mounts = [
    ['battery', -0.58, 1.02, 3.35, 1],
    ['carb', 0, 1.52, 3.35, 1],
    ['alternator', 0.58, 1.0, 3.35, 2],
    ['radiator', 0, 1.1, 3.6, 2],
    ['plugs', 0, 1.6, 3.25, 3],
    ['wheels', 2.5, 0.55, 0.95, 4]
  ]
  for (const [part, x, y, z, toolIdx] of mounts) {
    const spot = part === 'wheels'
      ? B.world.truck.group.localToWorld(new (B.world.truck.group.position.constructor)(0.94, 0.55, 1.55))
      : B.world.truck.group.localToWorld(new (B.world.truck.group.position.constructor)(x, y + 0.12, z - 3.35 + 3.35))
    if (part === 'wheels') {
      B.teleport(2.6, 0.95)
      B.face(spot.x, spot.y, spot.z)
    } else {
      B.teleport(x, 3.35)
      const local = B.world.truck.group.localToWorld(new (B.world.truck.group.position.constructor)(x, y + 0.12, z - 3.35))
