    window.dispatchEvent(new KeyboardEvent('keyup', { code: 'KeyE', key: 'e', bubbles: true }))
  }
  const spots = {
    battery:    { tool: 1, stand: [-0.58, 3.3], look: [-0.58, 1.14, 1.52] },
    carb:       { tool: 1, stand: [0, 3.15], look: [0, 1.64, 1.26] },
    alternator: { tool: 2, stand: [0.58, 3.4], look: [0.58, 1.12, 1.68] },
    radiator:   { tool: 2, stand: [0, 3.7], look: [0, 1.22, 1.92] },
    plugs:      { tool: 3, stand: [-0.5, 3.15], look: [-0.5, 1.72, 0.95] },
    wheels:     { tool: 4, stand: [2.6, 0.95], look: [0.94, 0.55, 0.95] }
  }
  const log = []
  for (const [part, cfg] of Object.entries(spots)) {
    if (!B.game.s.parts[part]) {
      // install if it is still carried
      if ((B.game.s.inventory[part] || 0) > 0) {
        B.teleport(cfg.stand[0], cfg.stand[1])
        B.face(...cfg.look)
        B.ui.onTool(cfg.tool)
        await frames(3)
        tap()
        await wait(420)
        B.ui.hideTorque()
        await frames(2)
      }
      if (!B.game.s.parts[part]) { log.push({ part, error: 'not installed' }); continue }
    }
    B.ui.onTool(cfg.tool)
    let guard = 0
    const results = []
    while (B.game.nextBolt(part) >= 0 && guard++ < 12) {
      if (!B.ui.torque || B.ui.torque.done) {
        B.teleport(cfg.stand[0], cfg.stand[1])
        B.face(...cfg.look)
        await frames(3)
        tap()
        await wait(300)
      }
      if (!B.ui.torque) { results.push('no-gauge'); break }
      const t = B.ui.torque
      const mid = (t.lo + t.hi) / 2
      B.ui.startHold()
      await wait(250)
      let spin = 0
      while (B.ui.torque === t && !t.done && t.value < mid && spin++ < 400) await frames(1)
      B.ui.releaseHold()
      await wait(1550)
      results.push(B.game.s.bolts[part][B.game.s.bolts[part].length - 1] || '?')
    }
    log.push({ part, bolts: B.game.s.bolts[part], results, next: B.game.nextBolt(part), panel: B.ui.panel })
  }
  return JSON.stringify(log)
})()

